            'events'=>$id."user_id bigint(20) unsigned NOT NULL, request_key varchar(80) NOT NULL, request_hash varchar(64) NOT NULL, response_json longtext NOT NULL, created_at datetime NOT NULL, PRIMARY KEY  (id), UNIQUE KEY owned_request (user_id,request_key)",
