    }
    private static function plan_data($d){
        $allowed=array('request_key','expected_revision','title','course','scheme','group','exam_month','exam_year','target_kind','target_date','start_date','timezone','daily_minutes','question_target','chapter_target','weekdays','from_plan_id','carry_progress');if(array_diff(array_keys($d),$allowed))return self::error('Unexpected study-plan fields.');
