        $kind=$d['target_kind']??'personal';if(!in_array($kind,array('personal','month_end'),true))return self::error('No verified official timetable is indexed. Choose a personal or labelled month-end planning target.');$target=$kind==='month_end'?(new DateTimeImmutable($period.'-01'))->format('Y-m-t'):self::date($d['target_date']??'');$start=self::date($d['start_date']??'');if(is_wp_error($target))return $target;if(is_wp_error($start))return $start;if($start>$target||(new DateTimeImmutable($start))->diff(new DateTimeImmutable($target))->days>3660)return self::error('Start must precede the target, within a ten-year planning window.');
        $minutes=self::integer($d['daily_minutes']??0,1,1440);if(is_wp_error($minutes))return $minutes;$days=$d['weekdays']??null;if(!is_array($days)||!array_is_list($days)||!$days||count($days)>7)return self::error('Select at least one study day.');foreach($days as $day)if(!is_int($day)||$day<1||$day>7)return self::error('Study days must be Monday (1) through Sunday (7).');$days=array_values(array_unique($days));sort($days);
