    public static function save_plan($input,$id=0){return self::write('plan:'.$id,$input,function()use($input,$id){
        $d=self::plan_data($input);if(is_wp_error($d))return $d;global $wpdb;$plans=self::table('plans');$uid=get_current_user_id();$before=$id?self::plan($id):null;if(is_wp_error($before))return $before;
        if($before){if(($input['expected_revision']??null)!==$before['revision'])return self::error('Plan changed; reload before saving.',409);foreach(array('course','scheme','group') as $k)if($d[$k]!==$before['data'][$k])return self::error('Create a revised plan to change course or group. Earlier history will be preserved.');}
        $now=current_time('mysql',true);$row=array('title'=>$d['title'],'course'=>$d['course'],'target_date'=>$d['target_date'],'payload'=>wp_json_encode($d),'revision'=>$before?$before['revision']+1:1,'updated_at'=>$now);
