            foreach(CAFCC_Courses::subjects($d['course'],$d['group']) as $s)if(false===$wpdb->insert(self::table('subjects'),array('user_id'=>$uid,'plan_id'=>$id,'subject_key'=>$s['key'],'title'=>$s['title'],'short_title'=>$s['short'],'group_number'=>$s['group'])))return self::error('Cannot retain the paper snapshot.',503);
            if($oldactive)$wpdb->update($plans,array('archived'=>1),array('id'=>$oldactive,'user_id'=>$uid));$wpdb->update(self::table('owners'),array('active_plan_id'=>$id),array('user_id'=>$uid));
            if(!empty($input['from_plan_id'])){$old=self::plan((int)$input['from_plan_id']);if(is_wp_error($old))return $old;if($old['course']!==$d['course'])return self::error('A revised plan can carry chapter entries only within the same course.');$keys=array_column(self::subjects($id),'subject_key');$entries=$wpdb->get_results($wpdb->prepare('SELECT * FROM '.self::table('entries')." WHERE user_id=%d AND plan_id=%d AND kind='item' ORDER BY id LIMIT 1000",$uid,$old['id']),ARRAY_A);$map=array();foreach($entries as $e){if(!in_array($e['subject_key'],$keys,true))continue;$prior=$e['id'];unset($e['id']);$e['plan_id']=$id;$e['revision']=1;$e['parent_id']=$map[$e['parent_id']]??0;$payload=json_decode($e['payload'],true);$payload['carried_from_id']=(int)$prior;if(empty($input['carry_progress'])){$e['status']='not_started';$e['completed_date']=null;$payload['first_done']=$payload['r1_done']=$payload['r2_done']=false;}$e['payload']=wp_json_encode($payload);$e['created_at']=$e['updated_at']=$now;if(false===$wpdb->insert(self::table('entries'),$e))return self::error('Cannot retain revised chapter snapshots.',503);$map[$prior]=$wpdb->insert_id;}}
        }
        $after=self::plan($id);if(!self::audit($id,'plan',$id,$row['revision'],$before,$after))return self::error('Cannot retain plan history.',503);return $after;
    });}
    public static function activate($id,$input){return self::write('activate:'.$id,$input,function()use($id,$input){if(array_diff(array_keys($input),array('request_key')))return self::error('Unexpected activation fields.');$p=self::plan($id);if(is_wp_error($p))return $p;global $wpdb;$uid=get_current_user_id();$old=(int)$wpdb->get_var($wpdb->prepare('SELECT active_plan_id FROM '.self::table('owners').' WHERE user_id=%d',$uid));if($old)$wpdb->update(self::table('plans'),array('archived'=>1),array('id'=>$old,'user_id'=>$uid));$wpdb->update(self::table('plans'),array('archived'=>0),array('id'=>$id,'user_id'=>$uid));$wpdb->update(self::table('owners'),array('active_plan_id'=>$id),array('user_id'=>$uid));if(!self::audit($id,'active_plan',$id,$p['revision'],array('old_plan'=>$old),array('active_plan'=>$id)))return self::error('Cannot retain plan selection.',503);return array('active_plan_id'=>$id);});}
    public static function catalog(){if(is_wp_error($e=self::allowed()))return $e;global $wpdb;$uid=get_current_user_id();return array('courses'=>array_values(CAFCC_Courses::all()),'active_plan_id'=>(int)$wpdb->get_var($wpdb->prepare('SELECT active_plan_id FROM '.self::table('owners').' WHERE user_id=%d',$uid)),'plans'=>$wpdb->get_results($wpdb->prepare('SELECT id,title,course,archived,revision,target_date FROM '.self::table('plans').' WHERE user_id=%d ORDER BY id DESC LIMIT 100',$uid),ARRAY_A),'today'=>current_datetime()->format('Y-m-d'),'timezone'=>wp_timezone_string(),'official_timetable_available'=>false);}
    private static function subject_ok($plan,$key,$optional=false){if($optional&&$key==='')return true;return is_string($key)&&in_array($key,array_column(self::subjects($plan),'subject_key'),true);}
    private static function today($plan){return (new DateTimeImmutable('now',new DateTimeZone($plan['data']['timezone'])))->format('Y-m-d');}
    private static function number($v,$max){if(!is_int($v)&&!is_float($v))return self::error('Enter a number.');return is_finite((float)$v)&&$v>=0&&$v<=$max?round((float)$v,2):self::error('Number exceeds its allowed range.');}
    private static function validate_entry($plan,$kind,$d,$old){
