        $extras=array('item'=>array('item_type','difficulty','priority','estimated_minutes','actual_minutes','first_done','r1_done','r2_done'),'task'=>array('question_target','chapter_target'),'revision'=>array('cycle','difficulty','next_date'),'mock'=>array('mock_type','maximum_marks','marks_obtained','retest_needed','improvement','resource_id','mcq_test_key','mock_round'),'log'=>array('questions','chapters'));
        if(!isset($extras[$kind])||array_diff(array_keys($d),array_merge($common,$extras[$kind])))return self::error('Unexpected planner record fields.');
