        $title=self::text($d['title']??'');$notes=self::text($d['notes']??'',4000);if(is_wp_error($title)||is_wp_error($notes)||!$title)return self::error('Use a short title and bounded private notes.');
        $date=self::date($d['scheduled_date']??null,true);$actual=self::date($d['completed_date']??null,true);if(is_wp_error($date))return $date;if(is_wp_error($actual))return $actual;$today=self::today($plan);if($actual&&$actual>$today)return self::error('Actual completion cannot be in the future.');
        $minutes=self::integer($d['minutes']??0,0,14400);if(is_wp_error($minutes))return $minutes;$parent=$d['parent_id']??0;if(!is_int($parent)||$parent<0)return self::error('Choose an owned parent chapter.');if($old&&$parent!==$old['parent_id'])return self::error('Parent identity is retained. Create a new item to change its hierarchy.');if($parent){$p=self::entry($parent);if(is_wp_error($p)||$p['plan_id']!==$plan['id']||$p['kind']!=='item'||$p['subject_key']!==$subject)return self::error('Parent must be your own chapter in this subject.');}
        $status=$d['status']??($kind==='item'?'not_started':'planned');$payload=array('notes'=>$notes);$allowed=$kind==='item'?array('not_started','in_progress','first_completed','revision1_completed','revision2_completed','more_revision_needed'):($kind==='log'?array('recorded'):array('planned','completed','postponed'));
        if(!in_array($status,$allowed,true))return self::error('Choose an available status.');if($status==='completed'&&!$actual)$actual=$today;
        if($kind==='item'){
            $payload=array_merge($old['data']??array(),$payload);$payload['item_type']=$d['item_type']??'chapter';if(!in_array($payload['item_type'],array('chapter','unit','topic'),true))return self::error('Choose chapter, unit or topic.');$payload['origin']=$payload['origin']??'student_defined';
            foreach(array('difficulty'=>array('unset','easy','medium','hard'),'priority'=>array('normal','high','low')) as $key=>$values){$payload[$key]=$d[$key]??$values[0];if(!in_array($payload[$key],$values,true))return self::error('Choose a displayed difficulty/priority.');}
            foreach(array('estimated_minutes','actual_minutes') as $k){$payload[$k]=self::integer($d[$k]??0,0,100000);if(is_wp_error($payload[$k]))return $payload[$k];}
            foreach(array('first_done','r1_done','r2_done') as $k){if(isset($d[$k])&&!is_bool($d[$k]))return self::error('Completion flags must be true or false.');$payload[$k]=$d[$k]??($payload[$k]??false);}
            if(in_array($status,array('first_completed','revision1_completed','revision2_completed'),true)){$payload['first_done']=true;if(!$actual)$actual=$today;}if(in_array($status,array('revision1_completed','revision2_completed'),true))$payload['r1_done']=true;if($status==='revision2_completed')$payload['r2_done']=true;
            if($status==='not_started'){$payload['first_done']=$payload['r1_done']=$payload['r2_done']=false;$actual=null;}
        }elseif($kind==='revision'){
            $cycle=$d['cycle']??'1';if(!is_string($cycle)||!in_array($cycle,array('1','2','3','custom'),true))return self::error('Choose revision 1, 2, 3 or custom.');$payload['cycle']=$cycle;$payload['difficulty']=$d['difficulty']??'unset';if(!in_array($payload['difficulty'],array('unset','easy','medium','hard'),true))return self::error('Choose a displayed difficulty.');$payload['next_date']=self::date($d['next_date']??null,true);if(is_wp_error($payload['next_date']))return $payload['next_date'];if(!$date)return self::error('Choose a planned revision date.');
        }elseif($kind==='mock'){
            $payload['mock_round']=$d['mock_round']??'1';if(!in_array($payload['mock_round'],array('1','2','custom'),true))return self::error('Choose mock round 1, 2 or custom.');$payload['mock_type']=$d['mock_type']??'self_created';if(!in_array($payload['mock_type'],array('self_created','icai_mtp','group_mock','in_app_mcq'),true))return self::error('Choose the mock source.');$payload['retest_needed']=$d['retest_needed']??false;if(!is_bool($payload['retest_needed']))return self::error('Retest must be true or false.');$payload['improvement']=self::text($d['improvement']??'',2000);if(is_wp_error($payload['improvement']))return $payload['improvement'];
            $max=$d['maximum_marks']??null;$marks=$d['marks_obtained']??null;if($max!==null){$max=self::number($max,10000);if(is_wp_error($max)||$max<=0)return self::error('Maximum marks must be positive.');}if($marks!==null){$marks=self::number($marks,10000);if(is_wp_error($marks)||$max===null||$marks>$max)return self::error('Recorded marks require a valid maximum and cannot exceed it.');}if($status!=='completed'&&$marks!==null)return self::error('Record marks only for a completed mock.');$payload['maximum_marks']=$max;$payload['marks_obtained']=$marks;$payload['score_origin']='student_reported';$resource=$d['resource_id']??0;if(!is_int($resource)||$resource<0)return self::error('Choose an indexed resource.');if($payload['mock_type']==='icai_mtp'){if(!class_exists('CAFCC_Resource_Matrix')||!CAFCC_Resource_Matrix::mtp($resource,$plan['course'],$subject))return self::error('Choose an indexed, source-verified MTP resource.');$payload['resource_id']=$resource;}
            if($payload['mock_type']==='in_app_mcq'){if($plan['course']!=='final')return self::error('The indexed MCQ tests belong to CA Final, not this course.');$key=$d['mcq_test_key']??'';if(!is_string($key)||!preg_match('/^[a-f0-9-]{36}$/D',$key))return self::error('Choose one of your submitted in-app MCQ tests.');$test=CAFCC_MCQ_Student::test_get($key);if(is_wp_error($test)||$test['status']!=='submitted')return self::error('Your completed MCQ test is unavailable.');$test_items=json_decode($test['payload'],true)['items'];if($subject)foreach($test_items as $it){$q=CAFCC_MCQ::get((int)$it['id']);if(!$q||$q['subject_code']!==$subject)return self::error('This scored test does not match the selected mock subject.');}$result=json_decode($test['result'],true);if((int)$result['scored_question_count']<1)return self::error('That MCQ test has no scored questions.');$payload['maximum_marks']=(float)$result['scored_question_count'];$payload['marks_obtained']=(float)$result['score'];$payload['score_origin']='recorded_in_app_mcq_practice';$payload['mcq_test_key']=$key;$status='completed';$actual=(new DateTimeImmutable($test['submitted_at'],new DateTimeZone('UTC')))->setTimezone(new DateTimeZone($plan['data']['timezone']))->format('Y-m-d');$minutes=(int)ceil(($result['duration_seconds']??0)/60);}
            if(!$date)return self::error('Choose a mock date.');
        }else{
            foreach($kind==='log'?array('questions','chapters'):array('question_target','chapter_target') as $k){$payload[$k]=self::integer($d[$k]??0,0,10000);if(is_wp_error($payload[$k]))return $payload[$k];}
            if(!$date)return self::error('Choose a date.');if($kind==='log'){if($date>$today||$minutes>1440)return self::error('Study logs record actual past/today minutes, at most 24 hours per day.');$actual=$date;}
        }
        return array('subject_key'=>$subject,'parent_id'=>$parent,'title'=>$title,'status'=>$status,'scheduled_date'=>$date,'completed_date'=>$actual,'minutes'=>$minutes,'payload'=>wp_json_encode($payload));
    }
    public static function save_entry($plan_id,$kind,$input,$id=0){if(!is_string($kind)||!in_array($kind,array('item','task','revision','mock','log'),true))return self::error('Choose an available planner record type.');return self::write('entry:'.$kind.':'.$id,$input,function()use($plan_id,$kind,$input,$id){
        $plan=self::plan($plan_id);if(is_wp_error($plan))return $plan;$old=$id?self::entry($id):null;if(is_wp_error($old))return $old;if($old&&($old['plan_id']!==$plan_id||$old['kind']!==$kind))return self::error('Record does not belong to this plan.',404);if($old&&($input['expected_revision']??null)!==$old['revision'])return self::error('Planner record changed; reload before saving.',409);
        $row=self::validate_entry($plan,$kind,$input,$old);if(is_wp_error($row))return $row;global $wpdb;$t=self::table('entries');$uid=get_current_user_id();if(!$old&&(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $t WHERE user_id=%d AND plan_id=%d AND kind=%s",$uid,$plan_id,$kind))>=2000)return self::error('This plan has reached its record limit; create a revised plan.');
        if($kind==='log'){$sum=(int)$wpdb->get_var($wpdb->prepare("SELECT COALESCE(SUM(minutes),0) FROM $t WHERE user_id=%d AND plan_id=%d AND kind='log' AND scheduled_date=%s AND id<>%d",$uid,$plan_id,$row['scheduled_date'],$id));if($sum+$row['minutes']>1440)return self::error('Total logged time for this date cannot exceed 24 hours.');}
        $now=current_time('mysql',true);$row['revision']=$old?$old['revision']+1:1;$row['updated_at']=$now;if($old){if(false===$wpdb->update($t,$row,array('id'=>$id,'user_id'=>$uid)))return self::error('Cannot save planner record.',503);}else{$row+=array('user_id'=>$uid,'plan_id'=>$plan_id,'kind'=>$kind,'created_at'=>$now);if(false===$wpdb->insert($t,$row))return self::error('Cannot retain planner record.',503);$id=(int)$wpdb->insert_id;}
        $after=self::entry($id);if(!self::audit($plan_id,$kind,$id,$row['revision'],$old,$after))return self::error('Cannot retain planner revision.',503);
        if($kind==='revision'&&$row['status']==='completed'&&$row['parent_id']){$parent=self::entry($row['parent_id']);$cycle=$after['data']['cycle'];if(in_array($cycle,array('1','2'),true)){$pd=$parent['data'];$pd[$cycle==='1'?'r1_done':'r2_done']=true;$pd['first_done']=true;$v=array('payload'=>wp_json_encode($pd),'revision'=>$parent['revision']+1,'updated_at'=>$now);$wpdb->update($t,$v,array('id'=>$parent['id'],'user_id'=>$uid));if(!self::audit($plan_id,'item',$parent['id'],$v['revision'],$parent,self::entry($parent['id'])))return self::error('Cannot retain linked revision.',503);}}
        return $after;
    });}
    public static function entries($id,$r){if(is_wp_error($e=self::allowed()))return $e;$plan=self::plan($id);if(is_wp_error($plan))return $plan;$kind=$r->get_param('kind')??'item';if(!in_array($kind,array('item','task','revision','mock','log'),true))return self::error('Unknown planner view.');$subject=$r->get_param('subject')??'';if(!is_string($subject)||($subject&&!self::subject_ok($id,$subject)))return self::error('Unknown planned subject.');$page=max(1,(int)($r->get_param('page')??1));if($page>10000)return self::error('Invalid page.');$filter=$r->get_param('due')??'all';if(!in_array($filter,array('all','today','upcoming','overdue','completed'),true))return self::error('Unknown due filter.');global $wpdb;$t=self::table('entries');$where='user_id=%d AND plan_id=%d AND kind=%s';$args=array(get_current_user_id(),$id,$kind);if($subject){$where.=' AND subject_key=%s';$args[]=$subject;}$today=self::today($plan);if($filter==='completed')$where.=" AND status IN ('completed','recorded')";elseif($filter!=='all'){$where.=" AND status NOT IN ('completed','recorded') AND scheduled_date ".array('today'=>'=','upcoming'=>'>','overdue'=>'<')[$filter].' %s';$args[]=$today;}$count=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $t WHERE $where",$args));$rows=$wpdb->get_col($wpdb->prepare("SELECT id FROM $t WHERE $where ORDER BY COALESCE(scheduled_date,'9999-12-31'),id LIMIT 50 OFFSET %d",array_merge($args,array(($page-1)*50))));$items=array_map(array(__CLASS__,'entry'),$rows);return array('items'=>$items,'total'=>$count,'page'=>$page,'per_page'=>50,'today'=>$today);}
    public static function templates($subject){global $wpdb;$s=CAFCC_DB::table('subjects');$e=CAFCC_DB::table('editions');return $wpdb->get_results($wpdb->prepare("SELECT e.id,e.title,e.edition_key,e.applicability,e.source_url FROM $e e JOIN $s s ON s.id=e.subject_id WHERE s.code=%s AND ".CAFCC_Owner::usable_sql('e')." ORDER BY e.id DESC LIMIT 30",$subject),ARRAY_A);}
    public static function import_template($id,$input){return self::write('template:'.$id,$input,function()use($id,$input){if(array_diff(array_keys($input),array('request_key','subject_key','edition_id','include_details')))return self::error('Unexpected template fields.');$p=self::plan($id);if(is_wp_error($p))return $p;$subject=$input['subject_key']??'';$edition=$input['edition_id']??0;if($p['course']!=='final'||!self::subject_ok($id,$subject)||!is_int($edition)||!in_array($edition,array_map('intval',array_column(self::templates($subject),'id')),true))return self::error('Choose an indexed edition for a subject in this plan.');$details=$input['include_details']??false;if(!is_bool($details))return self::error('Detailed headings must be true or false.');global $wpdb;$n=CAFCC_DB::table('taxonomy');$c=CAFCC_Bank_DB::table('closure');$rows=$wpdb->get_results($wpdb->prepare("SELECT n.* FROM $n n WHERE n.edition_id=%d AND n.heading_origin='official' AND n.source_url<>'' AND ".CAFCC_Owner::usable_sql('n')." AND NOT EXISTS(SELECT 1 FROM $c c JOIN $n a ON a.id=c.ancestor_id WHERE c.descendant_id=n.id AND NOT (".CAFCC_Owner::usable_sql('a').")) AND n.node_type IN (".($details?"'chapter','unit','topic','subtopic'":"'chapter'").") ORDER BY n.id LIMIT 1000",$edition),ARRAY_A);if(!$rows)return self::error('No source-backed published headings are indexed in that edition. Add clearly labelled custom chapters.');$t=self::table('entries');$added=0;$parents=array();foreach($rows as $r){$old=$wpdb->get_var($wpdb->prepare("SELECT id FROM $t WHERE user_id=%d AND plan_id=%d AND kind='item' AND academic_node_id=%d",get_current_user_id(),$id,$r['id']));if($old){$parents[$r['id']]=$old;continue;}$payload=array('notes'=>'','item_type'=>$r['node_type']==='subtopic'?'topic':$r['node_type'],'origin'=>'source_backed_snapshot','source_title'=>$r['title'],'source_url'=>$r['source_url'],'source_location'=>$r['source_location'],'edition_id'=>$edition,'first_done'=>false,'r1_done'=>false,'r2_done'=>false,'difficulty'=>'unset','priority'=>'normal','estimated_minutes'=>0,'actual_minutes'=>0);$now=current_time('mysql',true);$v=array('user_id'=>get_current_user_id(),'plan_id'=>$id,'kind'=>'item','subject_key'=>$subject,'parent_id'=>$parents[$r['parent_id']]??0,'academic_node_id'=>$r['id'],'title'=>$r['title'],'status'=>'not_started','payload'=>wp_json_encode($payload),'created_at'=>$now,'updated_at'=>$now);if(false===$wpdb->insert($t,$v))return self::error('Cannot retain syllabus snapshot.',503);$parents[$r['id']]=$wpdb->insert_id;$added++;}if(!self::audit($id,'template',$edition,1,null,array('subject'=>$subject,'edition_id'=>$edition,'added'=>$added)))return self::error('Cannot retain template provenance.',503);return array('added'=>$added,'retained'=>count($rows)-$added,'note'=>'Personal plan snapshot. Confirm the selected edition applicability; no academic records or practice status were changed.');});}
    public static function summary($id){
        if(is_wp_error($e=self::allowed()))return $e;$p=self::plan($id);if(is_wp_error($p))return $p;global $wpdb;$uid=get_current_user_id();$t=self::table('entries');$subjects=self::subjects($id);$today=self::today($p);$zone=new DateTimeZone($p['data']['timezone']);$now=new DateTimeImmutable($today,$zone);$week=$now->modify('monday this week')->format('Y-m-d');$end=$now->modify('sunday this week')->format('Y-m-d');
        $groups=$wpdb->get_results($wpdb->prepare("SELECT subject_key,COUNT(*) AS planned,SUM(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.first_done'))='true') AS first_done,SUM(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.r1_done'))='true') AS r1_done,SUM(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.r2_done'))='true') AS r2_done FROM $t WHERE user_id=%d AND plan_id=%d AND kind='item' AND JSON_UNQUOTE(JSON_EXTRACT(payload,'$.item_type'))='chapter' GROUP BY subject_key",$uid,$id),ARRAY_A);$map=array_column($groups,null,'subject_key');$hours=$wpdb->get_results($wpdb->prepare("SELECT subject_key,SUM(minutes) AS minutes FROM $t WHERE user_id=%d AND plan_id=%d AND kind='log' GROUP BY subject_key",$uid,$id),ARRAY_A);$h=array_column($hours,'minutes','subject_key');$totals=array('planned'=>0,'first_done'=>0,'r1_done'=>0,'r2_done'=>0);foreach($subjects as &$s){$x=$map[$s['subject_key']]??array();foreach(array_keys($totals) as $k){$s[$k]=(int)($x[$k]??0);$totals[$k]+=$s[$k];}$s['logged_minutes']=(int)($h[$s['subject_key']]??0);$s['practice_url']=add_query_arg(array('cafcc_view'=>'practice','subject'=>$s['subject_key']),home_url('/'));}unset($s);
        $mocks=$wpdb->get_results($wpdb->prepare("SELECT id,title,status,completed_date,subject_key,payload FROM $t WHERE user_id=%d AND plan_id=%d AND kind='mock' ORDER BY COALESCE(completed_date,scheduled_date),id LIMIT 2000",$uid,$id),ARRAY_A);$scores=array();$done=0;$mock_subjects=array();$rounds=array('1'=>array('planned'=>0,'completed'=>0),'2'=>array('planned'=>0,'completed'=>0),'custom'=>array('planned'=>0,'completed'=>0));foreach($mocks as $m){$key=$m['subject_key'];if(!isset($mock_subjects[$key]))$mock_subjects[$key]=array('planned'=>0,'completed'=>0);$mock_subjects[$key]['planned']++;if($m['status']==='completed')$mock_subjects[$key]['completed']++;$round=json_decode($m['payload'],true)['mock_round']??'1';$rounds[$round]['planned']++;if($m['status']==='completed'){$done++;$rounds[$round]['completed']++;}$d=json_decode($m['payload'],true);if($m['status']==='completed'&&isset($d['marks_obtained'],$d['maximum_marks'])&&$d['maximum_marks']>0)$scores[]=array('id'=>(int)$m['id'],'title'=>$m['title'],'subject_key'=>$m['subject_key'],'date'=>$m['completed_date'],'percent'=>round(100*$d['marks_obtained']/$d['maximum_marks'],2),'marks'=>$d['marks_obtained'],'maximum'=>$d['maximum_marks'],'origin'=>$d['score_origin']);}
        foreach($subjects as &$subject){$subject['mocks_planned']=$mock_subjects[$subject['subject_key']]['planned']??0;$subject['mocks_completed']=$mock_subjects[$subject['subject_key']]['completed']??0;}unset($subject);
        $daily=$wpdb->get_row($wpdb->prepare("SELECT COALESCE(SUM(minutes),0) AS minutes,COALESCE(SUM(JSON_EXTRACT(payload,'$.questions')),0) AS questions,COALESCE(SUM(JSON_EXTRACT(payload,'$.chapters')),0) AS chapters FROM $t WHERE user_id=%d AND plan_id=%d AND kind='log' AND scheduled_date=%s",$uid,$id,$today),ARRAY_A);$weekly=$wpdb->get_row($wpdb->prepare("SELECT COALESCE(SUM(minutes),0) AS minutes FROM $t WHERE user_id=%d AND plan_id=%d AND kind='log' AND scheduled_date BETWEEN %s AND %s",$uid,$id,$week,$end),ARRAY_A);$study_today=in_array((int)$now->format('N'),$p['data']['weekdays'],true)&&$today>=$p['data']['start_date']&&$today<=$p['target_date'];$week_days=0;for($i=0;$i<7;$i++){$day=(new DateTimeImmutable($week,$zone))->modify('+'.$i.' days');if(in_array((int)$day->format('N'),$p['data']['weekdays'],true)&&$day->format('Y-m-d')>=$p['data']['start_date']&&$day->format('Y-m-d')<=$p['target_date'])$week_days++;}
        $due=$wpdb->get_results($wpdb->prepare("SELECT kind,SUM(status='completed') AS completed,SUM(status<>'completed' AND scheduled_date<%s) AS overdue,SUM(status<>'completed' AND scheduled_date=%s) AS today,COUNT(*) AS planned FROM $t WHERE user_id=%d AND plan_id=%d AND kind IN ('task','revision','mock') GROUP BY kind",$today,$today,$uid,$id),ARRAY_A);$upcoming=$wpdb->get_col($wpdb->prepare("SELECT id FROM $t WHERE user_id=%d AND plan_id=%d AND kind IN ('task','revision','mock') AND status<>'completed' ORDER BY scheduled_date,id LIMIT 12",$uid,$id));$days=(int)$now->diff(new DateTimeImmutable($p['target_date'],$zone))->format('%r%a');
        return array('plan'=>$p,'subjects'=>$subjects,'totals'=>$totals,'today'=>$today,'days_remaining'=>max(0,$days),'target_passed'=>$days<0,'daily'=>array('target_minutes'=>$study_today?$p['data']['daily_minutes']:0,'target_questions'=>$study_today?$p['data']['question_target']:0,'target_chapters'=>$study_today?$p['data']['chapter_target']:0,'logged'=>$daily),'weekly'=>array('target_minutes'=>$week_days*$p['data']['daily_minutes'],'logged_minutes'=>(int)$weekly['minutes']),'mock_summary'=>array('rounds'=>$rounds,'planned'=>count($mocks),'completed'=>$done,'average_recorded_percent'=>$scores?round(array_sum(array_column($scores,'percent'))/count($scores),2):null,'scored_count'=>count($scores),'scores'=>array_slice($scores,-100),'chart_note'=>'The chart shows the latest 100 scored mocks; totals include all recorded mocks in this plan.'),'due'=>$due,'upcoming'=>array_map(array(__CLASS__,'entry'),$upcoming),'note'=>'Chapter/revision completion and logged hours are student-reported planning records, not certified mastery. Hours use daily logs only; chapter, revision, mock and stopwatch durations are kept separate to avoid double counting.');
    }
    public static function preparation(){
        if(is_wp_error($e=self::allowed()))return $e;global $wpdb;$uid=get_current_user_id();$active=(int)$wpdb->get_var($wpdb->prepare('SELECT active_plan_id FROM '.self::table('owners').' WHERE user_id=%d',$uid));$plan=$active?self::summary($active):null;if(is_wp_error($plan))$plan=null;$course=$plan?$plan['plan']['course']:'final';$papers=CAFCC_Courses::all()[$course];$planned=$plan?array_column($plan['subjects'],null,'subject_key'):array();$subjects=array();
        foreach($papers['subjects'] as $paper){$row=array('key'=>$paper['key'],'title'=>$paper['title'],'short'=>$paper['short'],'group'=>$paper['group'],'attempted'=>0,'needs_revision'=>0,'active_seconds'=>0,'last_activity'=>null,'planned'=>$planned[$paper['key']]??null);$base=array('cafcc_view'=>'practice','subject'=>$paper['key']);$row['url']=add_query_arg(array_merge($base,array('tab'=>'all')),home_url('/'));$row['attempted_url']=add_query_arg(array_merge($base,array('tab'=>'attempted')),home_url('/'));$row['revision_url']=add_query_arg(array_merge($base,array('tab'=>'needs_revision')),home_url('/'));$row['time_url']=add_query_arg(array_merge($base,array('tab'=>'timed')),home_url('/'));$row['planner_url']=add_query_arg(array('cafcc_view'=>'planner','plan_tab'=>'syllabus','subject'=>$paper['key']),home_url('/'));
            if($course==='final'){foreach(array('attempted','needs_revision','timed') as $mode){$r=new WP_REST_Request('GET');$r->set_param('subject',$paper['key']);$r->set_param('tab',$mode);$f=CAFCC_Library::filters($r);[$from,$where,$args]=CAFCC_Library::query($f);$sql=$mode==='timed'?"SELECT COALESCE(SUM(session.active_seconds+CASE WHEN session.status='running' THEN GREATEST(0,".(int)time()."-session.last_tick) ELSE 0 END),0) $from WHERE $where":"SELECT COUNT(DISTINCT q.id) $from WHERE $where";$value=(int)$wpdb->get_var($args?$wpdb->prepare($sql,$args):$sql);$row[$mode==='timed'?'active_seconds':$mode]=$value;}
                $r=new WP_REST_Request('GET');$r->set_param('subject',$paper['key']);$f=CAFCC_Library::filters($r);[$from,$where,$args]=CAFCC_Library::query($f);$sql="SELECT MAX(GREATEST(COALESCE(session.started_at,0),COALESCE(UNIX_TIMESTAMP(personal.modified_at),0),COALESCE(UNIX_TIMESTAMP(notebook.updated_at),0),COALESCE(UNIX_TIMESTAMP(progress.updated_at),0))) $from WHERE $where";$row['last_activity']=(int)$wpdb->get_var($args?$wpdb->prepare($sql,$args):$sql)?:null;
            }$subjects[]=$row;
        }
        return array('course'=>$papers,'active_plan'=>$plan,'subjects'=>$subjects,'note'=>'Planner chapter/revision coverage is student-reported. Stopwatch activity and MCQ correctness remain separate measurements. No plan or official countdown is invented.');
    }
    public static function mcq_tests(){global $wpdb;$rows=$wpdb->get_results($wpdb->prepare("SELECT test_key,submitted_at,result FROM ".CAFCC_MCQ::table('tests')." WHERE user_id=%d AND status='submitted' ORDER BY id DESC LIMIT 30",get_current_user_id()),ARRAY_A);foreach($rows as &$r){$d=json_decode($r['result'],true);$r['label']=$r['submitted_at'].' · '.$d['score'].' / '.$d['scored_question_count'].' practice points';unset($r['result']);}return $rows;}
    public static function screen(){self::assets();return '<section class="cc-planner" data-planner><header class="cc-page-heading"><div><h1>Study Planner</h1><p>Your private plan. Your own reported progress.</p></div><label>Active / archived plans<select data-plan-picker aria-label="Select a saved study plan"></select></label></header><p role="status" data-plan-message></p><nav class="cc-planner-tabs" aria-label="Planner views" role="tablist"></nav><div data-plan-content></div></section>';}
    public static function assets(){CAFCC_Experience::assets();wp_enqueue_script('cafcc-planner',plugins_url('assets/planner.js',CAFCC_FILE),array('cafcc-net','cafcc-experience'),CAFCC_VERSION,true);wp_localize_script('cafcc-planner','CAFCCPlanner',array('url'=>rest_url('cafcc/v10/planner/'),'nonce'=>wp_create_nonce('wp_rest')));}
    public static function init(){add_action('rest_api_init',function(){
        $p=function($r){return CAFCC_REST::permission($r);};$body=function($r){return CAFCC_Studio::body($r,40000);};
        register_rest_route('cafcc/v10','/planner/catalog',array('methods'=>'GET','permission_callback'=>$p,'callback'=>array(__CLASS__,'catalog')));
        register_rest_route('cafcc/v10','/planner/plans',array('methods'=>'POST','permission_callback'=>$p,'callback'=>function($r)use($body){$d=$body($r);return is_wp_error($d)?$d:self::save_plan($d);}));
        register_rest_route('cafcc/v10','/planner/plans/(?P<id>[1-9][0-9]{0,17})',array(array('methods'=>'GET','permission_callback'=>$p,'callback'=>function($r){return self::summary((int)$r['id']);}),array('methods'=>'PUT','permission_callback'=>$p,'callback'=>function($r)use($body){$d=$body($r);return is_wp_error($d)?$d:self::save_plan($d,(int)$r['id']);})));
        register_rest_route('cafcc/v10','/planner/plans/(?P<id>[1-9][0-9]{0,17})/activate',array('methods'=>'POST','permission_callback'=>$p,'callback'=>function($r)use($body){$d=$body($r);return is_wp_error($d)?$d:self::activate((int)$r['id'],$d);}));
        register_rest_route('cafcc/v10','/planner/plans/(?P<id>[1-9][0-9]{0,17})/entries',array(array('methods'=>'GET','permission_callback'=>$p,'callback'=>function($r){return self::entries((int)$r['id'],$r);}),array('methods'=>'POST','permission_callback'=>$p,'callback'=>function($r)use($body){$d=$body($r);return is_wp_error($d)?$d:self::save_entry((int)$r['id'],$d['kind']??'',$d);}))); 
        register_rest_route('cafcc/v10','/planner/plans/(?P<id>[1-9][0-9]{0,17})/entries/(?P<entry>[1-9][0-9]{0,17})',array('methods'=>'PUT','permission_callback'=>$p,'callback'=>function($r)use($body){$d=$body($r);return is_wp_error($d)?$d:self::save_entry((int)$r['id'],$d['kind']??'',$d,(int)$r['entry']);}));
        register_rest_route('cafcc/v10','/planner/templates',array('methods'=>'GET','permission_callback'=>$p,'callback'=>function($r){if(is_wp_error($e=self::allowed()))return $e;$s=$r->get_param('subject')??'';return is_string($s)?self::templates($s):self::error('Choose a subject.');}));
        register_rest_route('cafcc/v10','/planner/plans/(?P<id>[1-9][0-9]{0,17})/template',array('methods'=>'POST','permission_callback'=>$p,'callback'=>function($r)use($body){$d=$body($r);return is_wp_error($d)?$d:self::import_template((int)$r['id'],$d);}));
        register_rest_route('cafcc/v10','/planner/mcq-tests',array('methods'=>'GET','permission_callback'=>$p,'callback'=>function(){return is_wp_error($e=self::allowed())?$e:self::mcq_tests();}));
        register_rest_route('cafcc/v10','/planner/plans/(?P<id>[1-9][0-9]{0,17})/history',array('methods'=>'GET','permission_callback'=>$p,'callback'=>function($r){if(is_wp_error($e=self::allowed()))return $e;$p=self::plan((int)$r['id']);if(is_wp_error($p))return $p;global $wpdb;return $wpdb->get_results($wpdb->prepare('SELECT entity_kind,entity_id,revision,before_json,after_json,created_at FROM '.self::table('audit').' WHERE user_id=%d AND plan_id=%d ORDER BY id DESC LIMIT 50',get_current_user_id(),$p['id']),ARRAY_A);}));
    });}
